  // Let's check the HTML of the top movers section
  let topMoversHTML = '';
  if (topMoversHeading) {
    let parent = topMoversHeading.parentElement;
    for (let i = 0; i < 3; i++) {
      if (parent && parent.parentElement) parent = parent.parentElement;
    }
    topMoversHTML = parent ? parent.innerHTML : '';
  }

  // Also check the Constituents tab element
  const tabs = Array.from(document.querySelectorAll('button, a, [role="tab"]')).map(el => ({
    tag: el.tagName,
    text: el.textContent.trim(),
    id: el.id,
    className: el.className,
    role: el.getAttribute('role'),
    href: el.getAttribute('href')
  }));

  return {
    topMoversHTMLSnippet: topMoversHTML.slice(0, 3000),
    tabs: tabs.filter(t => /constituent|summary|chart|factsheet/i.test(t.text))
  };
});

